#include <Cellerator/compiler/profile/expose_profile_inspection_and_diff_tooling_v1.hh>
#include <cstdio>
namespace cellerator::compiler::profile::v1 {namespace{profile_inspection_status_v1 done(int n,std::size_t cap,std::size_t*out){if(n<0)return profile_inspection_status_v1::invalid_argument;*out=static_cast<std::size_t>(n);return static_cast<std::size_t>(n)<cap?profile_inspection_status_v1::ok:profile_inspection_status_v1::insufficient_capacity;}}
profile_inspection_status_v1 dump_profile_summary_v1(const profile_inspection_state_v1&s,profile_inspection_format_v1 f,char*b,std::size_t c,std::size_t*n) noexcept{if(!b||!c||!n)return profile_inspection_status_v1::invalid_argument;int w=f==profile_inspection_format_v1::machine_json?std::snprintf(b,c,"{\"identity\":\"%llu:%llu\",\"revision\":%llu,\"confidence\":%.3f,\"range\":[%.3f,%.3f],\"expected_mutations\":%u,\"missing_evidence\":%u}",(unsigned long long)s.identity_high,(unsigned long long)s.identity_low,(unsigned long long)s.evidence_revision,s.confidence,s.minimum,s.maximum,s.expected_mutations,s.missing_evidence):std::snprintf(b,c,"profile %llu:%llu revision %llu confidence %.3f range [%.3f, %.3f]; expected mutations 0x%x; missing evidence 0x%x",(unsigned long long)s.identity_high,(unsigned long long)s.identity_low,(unsigned long long)s.evidence_revision,s.confidence,s.minimum,s.maximum,s.expected_mutations,s.missing_evidence);return done(w,c,n);}
profile_inspection_status_v1 diff_profile_states_v1(const profile_inspection_state_v1&a,const profile_inspection_state_v1&b,profile_inspection_format_v1 f,char*out,std::size_t c,std::size_t*n) noexcept{if(!out||!c||!n)return profile_inspection_status_v1::invalid_argument;int w=f==profile_inspection_format_v1::machine_json?std::snprintf(out,c,"{\"revision_delta\":%lld,\"confidence_delta\":%.3f,\"range_changed\":%s,\"mutation_xor\":%u,\"missing_xor\":%u}",(long long)b.evidence_revision-(long long)a.evidence_revision,b.confidence-a.confidence,(a.minimum!=b.minimum||a.maximum!=b.maximum)?"true":"false",a.expected_mutations^b.expected_mutations,a.missing_evidence^b.missing_evidence):std::snprintf(out,c,"revision %+lld; confidence %+.3f; range %s; mutation delta 0x%x; missing evidence delta 0x%x",(long long)b.evidence_revision-(long long)a.evidence_revision,b.confidence-a.confidence,(a.minimum!=b.minimum||a.maximum!=b.maximum)?"changed":"unchanged",a.expected_mutations^b.expected_mutations,a.missing_evidence^b.missing_evidence);return done(w,c,n);}
}  // namespace cellerator::compiler::profile::v1
